 extern "C" __device__
 void d256_cp_async_fp32_tile(
         float* destination,
         const float* source,
         long long source_index) {
     constexpr int shared_ld = 68;
     constexpr int global_ld = 256;
     const int row = threadIdx.x >> 4;
     const int col = (threadIdx.x & 15) * 4;
     const unsigned destination_base = static_cast<unsigned>(
         __cvta_generic_to_shared(destination));
     #pragma unroll
     for (int load = 0; load < 8; ++load) {
         const int current_row = row + load * 8;
         const unsigned destination_offset = static_cast<unsigned>(
             (current_row * shared_ld + col) * sizeof(float));
         const unsigned destination_shared =
             destination_base + destination_offset;
         const float* source_global =
             source + source_index + current_row * global_ld + col;
         asm volatile(
             "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
             :: "r"(destination_shared), "l"(source_global));
     }
     asm volatile("cp.async.commit_group;\n" ::);
 }

